use crate::wasi::clocks::wall_clock;

struct Node;

/// Converts seconds since the Unix epoch to a proleptic Gregorian (year, month, day).
/// Uses the civil-from-days algorithm; no external dependencies.
fn civil_date(unix_seconds: u64) -> (i64, u32, u32) {
    let days = (unix_seconds / 86_400) as i64;
    let z = days + 719_468;
    let era = if z >= 0 { z } else { z - 146_096 } / 146_097;
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = (doy - (153 * mp + 2) / 5 + 1) as u32;
    let m = if mp < 10 { mp + 3 } else { mp - 9 } as u32;
    let y = yoe + era * 400 + if m <= 2 { 1 } else { 0 };
    (y, m, d)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started = now.seconds;
        let (y, m, d) = civil_date(started);

        // The contract requires exactly 10 characters, which holds for years 0000..=9999.
        // A wall-clock reading outside that range is clamped to the last representable date.
        let date = if (0..=9999).contains(&y) {
            format!("{:04}-{:02}-{:02}", y, m, d)
        } else {
            String::from("9999-12-31")
        };

        RunInfo { date, started }
    }
}

export!(Node);
